<template>
  <section class="qc-membership" aria-label="灵感补给站">
    <header class="qc-hero"><div class="qc-hero-copy"><span class="qc-eyebrow"><i></i> MORE ROOM FOR YOUR IDEAS</span><h1>给灵感，<br>留足<span>下一程。</span></h1><p>选一份合适的补给，把想到的，继续做到。<br>套餐、余额与兑换，都在这里清楚安排。</p><div class="qc-hero-links"><a href="#qc-offers" @click.prevent="scrollTo('qc-offers')">探索创作补给<ClientIcon name="arrow" /></a><router-link to="/wallet">查看我的额度<ClientIcon name="arrowUpRight" /></router-link></div></div><div class="qc-supply-art" aria-hidden="true"><i class="qc-art-orbit"></i><div class="qc-gift"><i></i><i></i><i></i><b>Q</b></div><span class="qc-art-spark">✦</span><span class="qc-art-sticker"><ClientIcon name="spark" /> A LITTLE MORE POSSIBILITY</span></div><span class="qc-hero-number">QGAUSS / CREATIVE SUPPLIES<br>CHOOSE YOUR NEXT CHAPTER</span></header>
    <div v-if="disabled" class="qc-state"><span>✳</span><h2>补给站暂未开放</h2><p>本站暂未开启充值与兑换，可以继续探索当前可用的创作功能。</p><router-link to="/chat" class="qc-primary">返回灵感工作台<ClientIcon name="arrow" /></router-link></div>
    <template v-else>
      <div v-if="recovery" class="qc-recovery" role="status"><ClientIcon name="info" /><p>上次下单结果尚未确认。先取回同一笔订单，再继续选择。</p><button type="button" :disabled="!!busy" @click="recoverCheckout">继续确认<ClientIcon name="arrow" /></button></div>
      <section id="qc-offers" class="qc-offers" aria-labelledby="qc-offers-title">
        <div class="qc-section-heading"><div><span class="qc-eyebrow">A SUPPLY FOR EVERY CREATIVE MOOD</span><h2 id="qc-offers-title">你的节奏，你来选。</h2><p>以下次数一次到账，会员期限单独计算。各类次数不能互换。</p></div><button type="button" class="qc-refresh" :disabled="loading" @click="loadOffers"><ClientIcon name="refresh" />刷新套餐</button></div>
        <div class="qc-offer-tabs" aria-label="套餐类型"><button v-for="item in offerTabs" :key="item.key" type="button" :aria-pressed="offerFilter === item.key" @click="offerFilter = item.key">{{ item.label }}</button></div>
        <div v-if="loading" class="qc-loading" role="status"><BrandLoader :size="40" text="正在整理你的创作补给…" /><div class="qc-skeleton"><i v-for="n in 3" :key="n"></i></div></div>
        <div v-else-if="catalogError" class="qc-state" role="alert"><ClientIcon name="info" /><h3>这批补给，暂时没到</h3><p>{{ catalogError }}</p><button type="button" class="qc-primary" @click="loadOffers">重新读取<ClientIcon name="refresh" /></button></div>
        <div v-else-if="!filteredOffers.length" class="qc-state"><span>✳</span><h3>{{ offers.length ? '换一种补给，看看吧。' : '下一批灵感补给，准备中。' }}</h3><p>{{ offers.length ? '当前没有这类套餐，可以查看其他选择。' : '套餐上架后会出现在这里，余额与兑换入口仍可独立使用。' }}</p><button v-if="offers.length" type="button" class="qc-text-button" @click="offerFilter = ''">看看全部套餐</button></div>
        <div v-else class="qc-offer-grid"><article v-for="(offer, index) in filteredOffers" :key="offer.id" class="qc-offer-card" :style="{ '--qc-order': index % 3 }"><header><span class="qc-offer-serial">SUPPLY / {{ String(index + 1).padStart(2, '0') }}</span><span class="qc-offer-icon"><ClientIcon :name="offer.days ? 'spark' : 'apps'" /></span></header><span class="qc-offer-duration">{{ packageDuration(offer.days) }}</span><h3>{{ offer.name }}</h3><p class="qc-offer-description">{{ offer.des || '一份清楚的创作额度，给下一段想法留出空间。' }}</p><div class="qc-offer-price"><small>¥</small><strong>{{ checkoutMoney(offer.priceCents) }}</strong><span>一次付清</span></div><div class="qc-ticket-divider"><i></i><span>WHAT'S INSIDE</span><i></i></div><dl><div v-for="pool in WALLET_POOLS" :key="pool.key"><dt><ClientIcon :name="pool.icon" />{{ pool.label }}</dt><dd>{{ walletCount(offer[pool.key + 'Count']) }}<small> 次</small></dd></div></dl><button type="button" class="qc-primary" :disabled="!!busy || !offer.offerRevision || !offer.priceCents" @click="selectOffer(offer, $event)">选择这份补给<ClientIcon name="arrowUpRight" /></button><small class="qc-offer-foot">{{ offer.priceCents ? '确认明细后创建订单，尚未支付不会到账' : '当前套餐不可购买，请选择其他补给' }}</small></article></div>
      </section>
      <section class="qc-other-supplies" aria-label="余额与卡密">
        <article class="qc-money-card"><div class="qc-small-heading"><span class="qc-utility-icon"><ClientIcon name="wallet" /></span><div><span class="qc-eyebrow">A LITTLE EXTRA ROOM</span><h2>余额，也备一点。</h2></div></div><p>充值金额进入钱包余额，不自动兑换为模型或绘画次数。</p><form @submit.prevent="selectMoney"><label class="qc-amount"><span>¥</span><input v-model="amount" aria-label="充值金额" inputmode="decimal" maxlength="12" placeholder="输入金额" /><small>元</small></label><div class="qc-amount-presets"><button v-for="value in ['10', '30', '100']" :key="value" type="button" :aria-pressed="amount === value" @click="amount = value">¥{{ value }}</button></div><p v-if="amountError" class="qc-inline-error" role="alert">{{ amountError }}</p><button type="submit" class="qc-primary" :disabled="!!busy">查看充值明细<ClientIcon name="arrow" /></button></form></article>
        <article id="qc-redeem" class="qc-redeem-card"><div class="qc-small-heading"><span class="qc-utility-icon"><ClientIcon name="file" /></span><div><span class="qc-eyebrow">UNWRAP SOMETHING GOOD</span><h2>把小礼物，拆开。</h2></div></div><p>已有卡密？输入 12 位字母数字，查看到账结果。</p><form @submit.prevent="redeem"><label class="qc-code-input"><ClientIcon name="spark" /><input v-model="code" aria-label="兑换卡密" autocomplete="off" maxlength="40" placeholder="ABCD-EFGH-JKMN" @keydown.enter="onCodeEnter" /></label><div v-if="redeemMessage" class="qc-grant-message" role="status">{{ redeemMessage }}<router-link v-if="redeemUncertain" to="/wallet">查看我的兑换记录<ClientIcon name="arrowUpRight" /></router-link></div><div v-if="grant" class="qc-grant-message is-success" role="status"><ClientIcon name="check" /><span>兑换成功：{{ grantSummary(grant) }}</span></div><button type="submit" class="qc-primary" :disabled="!!busy || redeemUncertain">{{ busy === 'redeem' ? '正在拆开…' : '兑换这份能量' }}<ClientIcon name="arrow" /></button></form></article>
      </section>
      <section class="qc-orders" aria-labelledby="qc-orders-title"><div class="qc-section-heading"><div><span class="qc-eyebrow">YOUR SUPPLY JOURNAL</span><h2 id="qc-orders-title">每一份补给，都有回音。</h2><p>返回支付页面不代表支付成功，以这里读取的订单状态为准。</p></div><button type="button" class="qc-refresh" :disabled="orders.loading" @click="loadOrders"><ClientIcon name="refresh" />刷新订单</button></div><div class="qc-order-controls"><label><span>订单状态</span><select v-model="orderFilter" aria-label="订单状态"><option value="">全部状态</option><option v-for="(name, status) in orderStates" :key="status" :value="status">{{ name }}</option></select></label><span v-if="orders.total !== null && !orders.error">共 {{ orders.total }} 笔</span></div><div v-if="orders.loading" class="qc-loading" role="status"><BrandLoader :size="30" text="正在整理补给记录…" /></div><div v-else-if="orders.error" class="qc-state" role="alert"><h3>订单记录暂未更新</h3><p>{{ orders.error }}</p><button type="button" class="qc-text-button" @click="loadOrders">重新读取</button></div><div v-else-if="!orders.items.length" class="qc-state qc-empty-orders"><span>✧</span><h3>这一程，从一份好补给开始。</h3><p>创建订单后，可以在这里查看进度与明细。</p></div><div v-else class="qc-order-list" role="list" aria-label="我的订单"><article v-for="order in orders.items" :key="order.orderId" role="listitem"><span class="qc-order-icon"><ClientIcon :name="order.goodsType === 'money' ? 'wallet' : 'spark'" /></span><div class="qc-order-copy"><strong>{{ order.goodsName }}</strong><p>{{ walletDate(order.createdAt) }} · {{ order.orderId }}</p></div><div class="qc-order-amount"><b>¥{{ checkoutMoney(order.totalCents) }}</b><span :data-status="order.status">{{ orderState(order.status) }}</span></div><button type="button" class="qc-order-open" :aria-label="'查看订单：' + order.orderId" @click="openOrder(order.orderId, $event)">查看<ClientIcon name="arrowUpRight" /></button></article></div><nav class="qc-pagination" aria-label="订单分页"><button type="button" aria-label="上一页订单" :disabled="orders.loading || orders.page <= 1" @click="changeOrderPage(-1)"><ClientIcon name="chevronLeft" /></button><span>第 {{ orders.page }} 页<span v-if="orders.total !== null"> / {{ Math.max(1, Math.ceil(orders.total / orderPageSize)) }}</span></span><button type="button" aria-label="下一页订单" :disabled="orders.loading || orders.total === null || orders.page * orderPageSize >= orders.total" @click="changeOrderPage(1)"><ClientIcon name="chevronRight" /></button></nav></section>
      <section class="qc-faq" aria-label="补给说明"><details><summary>次数和会员期限，怎么区分？<ClientIcon name="plus" /></summary><p>套餐列出的次数一次发放到各自的购买额度，会员期限由套餐单独授予。会员每日额度取决于站点配置，不等于套餐次数每天重发。</p></details><details><summary>关闭弹窗，会取消订单吗？<ClientIcon name="plus" /></summary><p>关闭弹窗只停止查看。已创建的订单保留在订单列表。未支付订单会在明确关闭或到期后关闭，付款成功会更新为已支付。</p></details><details><summary>支付后没看到到账，怎么办？<ClientIcon name="plus" /></summary><p>回到订单记录刷新实际状态。支付渠道回调确认后才会发放权益，不要把支付页返回或二维码出现当成支付成功。</p></details></section>
    </template>
    <dialog ref="dialog" class="qc-checkout-dialog" aria-labelledby="qc-checkout-title" @cancel.prevent="closeCheckout" @close="onDialogClosed" @click="onBackdrop"><template v-if="checkout"><header><span class="qc-eyebrow">YOUR NEXT CHAPTER</span><button type="button" aria-label="关闭订单详情" @click="closeCheckout"><ClientIcon name="close" /></button></header><div class="qc-checkout-symbol"><ClientIcon :name="checkout.payload?.goodsType === 'money' || checkout.order?.goodsType === 'money' ? 'wallet' : 'spark'" /></div><h2 id="qc-checkout-title">{{ checkout.order ? orderState(checkout.order.status) : checkout.recovering ? '取回上一份补给。' : '确认这份，恰好合适。' }}</h2><p class="qc-checkout-name">{{ checkout.order?.goodsName || checkout.offer?.name || (checkout.payload?.goodsType === 'money' ? '钱包余额充值' : '下单结果待确认') }}</p><div v-if="checkout.order || checkout.offer || checkout.payload?.goodsType === 'money'" class="qc-checkout-price"><small>¥</small>{{ checkoutMoney(checkout.order?.totalCents ?? checkout.offer?.priceCents ?? checkoutCents(checkout.payload?.amountYuan)) }}</div><dl v-if="receiptOffer" class="qc-checkout-benefits"><div><dt>会员期限</dt><dd>{{ packageDuration(receiptOffer.days) }}</dd></div><div v-for="pool in WALLET_POOLS" :key="pool.key"><dt>{{ pool.label }}</dt><dd>{{ walletCount(receiptOffer[pool.key + 'Count']) }} 次</dd></div></dl><p v-if="checkout.order?.legacyEntitlements" class="qc-checkout-note">这笔历史订单没有下单权益快照，权益以原有履约规则处理。</p><p v-else-if="receiptOffer" class="qc-checkout-note">列出的次数一次到账，不是每日重发。已创建订单以这里的权益快照为准。</p><p v-else-if="checkout.payload?.goodsType === 'money' || checkout.order?.goodsType === 'money'" class="qc-checkout-note">充值金额进入钱包余额，各类模型 / 绘画次数仍分别记录。</p><div v-if="checkout.order" class="qc-checkout-meta"><span>数量 {{ checkout.order.count || 1 }} 份 · 订单号</span><code>{{ checkout.order.orderId }}</code><span v-if="checkout.order.expiresAt && checkout.order.status === 0">等待付款截至 {{ walletDate(checkout.order.expiresAt) }}（北京）</span></div><p v-if="checkout.error" class="qc-inline-error" role="alert">{{ checkout.error }}</p><p v-if="checkout.statusError" class="qc-inline-error" role="status">{{ checkout.statusError }}</p><div v-if="busy && busy !== 'redeem'" class="qc-checkout-loading" role="status"><BrandLoader :size="24" :text="busyLabel" /></div><template v-if="!checkout.order && checkout.payload"><p class="qc-checkout-note">确认后创建未支付订单，再查看付款方式；此步骤不会直接支付。</p><button v-if="!checkout.stale" type="button" class="qc-primary" :disabled="!!busy" @click="createOrder">{{ checkout.recovering ? '确认原下单结果' : '创建订单并获取付款方式' }}<ClientIcon name="arrow" /></button><button v-else type="button" class="qc-primary" @click="refreshChangedOffer">更新套餐，重新选择<ClientIcon name="refresh" /></button></template><template v-else-if="checkout.order?.status === 0"><div v-if="checkout.prep?.mock" class="qc-mock-note"><ClientIcon name="info" /><p>当前为模拟支付，不会产生真实扣款。仅在明确确认后模拟到账。</p></div><button v-if="checkout.paymentUncertain" type="button" class="qc-primary" :disabled="!!busy" @click="refreshStatus">先确认订单状态<ClientIcon name="refresh" /></button><a v-else-if="safePayHref && !busy" class="qc-primary" :href="safePayHref" target="_blank" rel="noopener noreferrer">前往支付页面<ClientIcon name="arrowUpRight" /></a><button v-else-if="checkout.prep?.mock" type="button" class="qc-primary" :disabled="!!busy" @click="confirmMockPayment">确认模拟支付<ClientIcon name="check" /></button><button v-else type="button" class="qc-primary" :disabled="!!busy" @click="preparePayment">获取付款方式<ClientIcon name="arrow" /></button><div class="qc-checkout-actions"><button type="button" :disabled="!!busy" @click="refreshStatus">刷新支付状态<ClientIcon name="refresh" /></button><button type="button" :disabled="!!busy || checkout.paymentUncertain" @click="closeOrder">关闭未支付订单<ClientIcon name="close" /></button></div></template><template v-else-if="checkout.order"><router-link v-if="checkout.order.status === 1" to="/wallet" class="qc-primary" @click="closeCheckout">查看到账额度<ClientIcon name="arrowUpRight" /></router-link><button v-else type="button" class="qc-primary" @click="closeCheckout">收好这张记录<ClientIcon name="check" /></button></template><button v-else type="button" class="qc-primary" @click="closeCheckout">返回订单列表<ClientIcon name="arrow" /></button></template></dialog>
  </section>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { api } from '../../api/client.js';
import { useAuth } from '../../stores/auth.js';
import { useBalance } from '../../stores/balance.js';
import { WALLET_POOLS, walletCount, walletDate, grantSummary } from '../../lib/wallet-presentation.js';
import { checkoutCents, checkoutMoney, packageDuration, orderState, paymentHref, cardCode, ownOrderId, pendingCheckout, orderBenefits } from '../../lib/checkout-presentation.js';
import ClientIcon from '../reference/ClientIcon.vue';
import BrandLoader from './BrandLoader.vue';
import './membership-studio.css';
const auth = useAuth(), route = useRoute(), sharedBalance = useBalance();
const offers = ref([]), loading = ref(true), disabled = ref(false), catalogError = ref(''), offerFilter = ref(''), amount = ref(''), amountError = ref(''), code = ref(''), grant = ref(null), redeemMessage = ref(''), redeemUncertain = ref(false), recovery = ref(null), busy = ref(''), dialog = ref(null), checkout = ref(null), orderFilter = ref('');
const orders = reactive({ items: [], total: null, page: 1, loading: false, error: '' }), orderPageSize = 6;
const offerTabs = [{ key: '', label: '全部补给' }, { key: 'member', label: '含会员期限' }, { key: 'counts', label: '只补充次数' }];
const orderStates = { 0: '等待付款', 1: '已支付', 2: '支付失败', 3: '已关闭', 4: '已退款' };
const filteredOffers = computed(() => offers.value.filter(p => offerFilter.value === 'member' ? p.days !== 0 : offerFilter.value === 'counts' ? p.days === 0 : true));
const receiptOffer = computed(() => checkout.value?.order ? orderBenefits(checkout.value.order.entitlements, checkout.value.order.count) : checkout.value?.offer);
const safePayHref = computed(() => paymentHref(checkout.value?.prep?.payUrl));
const busyLabel = computed(() => ({ create: '正在确认这笔订单…', prepare: '正在准备付款方式…', mock: '正在确认模拟结果…', close: '正在关闭订单…', detail: '正在读取订单…' })[busy.value] || '正在更新…');
const controllers = new Map();
let alive = true, owner = auth.user?.id, opener = null, poller = null;
const current = () => alive && !!owner && owner === auth.user?.id;
function scope(key) { controllers.get(key)?.abort(); const controller = new AbortController(); controllers.set(key, controller); const user = owner; return { signal: controller.signal, current: () => current() && owner === user && !controller.signal.aborted && controllers.get(key) === controller }; }
function orderPath(action, id) { return ({ detail: '/order/detail/', prepare: '/pay/prepare/', status: '/pay/status/', close: '/order/close/', mock: '/pay/mock/' })[action] + encodeURIComponent(id); }
function recoveryKey() { return 'qg:checkout-pending:' + owner; }
function readRecovery() { try { recovery.value = pendingCheckout(JSON.parse(sessionStorage.getItem(recoveryKey()) || 'null')); } catch { recovery.value = null; } }
function saveRecovery(payload) { recovery.value = payload; try { if (payload) sessionStorage.setItem(recoveryKey(), JSON.stringify(payload)); else sessionStorage.removeItem(recoveryKey()); } catch { /* In-memory recovery remains available. */ } }
async function showCheckout(value, event) { if (!current() || busy.value) return; controllers.get('checkout')?.abort(); controllers.get('status')?.abort(); opener = event?.currentTarget?.matches?.('button,a') ? event.currentTarget : document.activeElement; checkout.value = value; const context = checkout.value; await nextTick(); if (current() && checkout.value === context && !dialog.value.open) dialog.value.showModal(); }
function selectOffer(offer, event) { if (recovery.value) return recoverCheckout(event); if (!offer.offerRevision || !offer.priceCents) return; void showCheckout({ offer, payload: { goodsType: 'package', goodsId: offer.id, expectedOfferRevision: offer.offerRevision, requestKey: crypto.randomUUID() }, order: null, prep: null, error: '', statusError: '' }, event); }
function selectMoney(event) { const cents = checkoutCents(amount.value); amountError.value = cents === null ? '请输入 0.01–21474836.47 元，最多两位小数。' : ''; if (cents === null) return; if (recovery.value) return recoverCheckout(event); void showCheckout({ payload: { goodsType: 'money', amountYuan: checkoutMoney(cents), requestKey: crypto.randomUUID() }, order: null, prep: null, error: '', statusError: '' }, event); }
function recoverCheckout(event) { if (!recovery.value) return; void showCheckout({ payload: { ...recovery.value }, recovering: true, order: null, prep: null, error: '', statusError: '' }, event); }
async function loadOffers() { const req = scope('catalog'); loading.value = true; catalogError.value = ''; try { const data = await api.get('/crami/packages', { signal: req.signal }); if (!req.current()) return; offers.value = Array.isArray(data.items) ? data.items : []; disabled.value = false; } catch (e) { if (!req.current()) return; if (e.status === 404) disabled.value = true; else catalogError.value = e.message || '套餐暂未读取成功'; } finally { if (req.current()) loading.value = false; } }
async function loadOrders() { const req = scope('orders'); orders.loading = true; orders.error = ''; const query = new URLSearchParams({ page: String(orders.page), pageSize: String(orderPageSize) }); if (orderFilter.value !== '') query.set('status', orderFilter.value); try { const data = await api.get('/order/list?' + query, { signal: req.signal }); if (!req.current()) return; orders.items = Array.isArray(data.items) ? data.items : []; orders.total = Number.isSafeInteger(data.total) ? data.total : null; } catch (e) { if (req.current()) { orders.items = []; orders.total = null; orders.error = e.message || '订单暂未读取成功'; } } finally { if (req.current()) orders.loading = false; } }
function changeOrderPage(delta) { if (orders.loading || orders.page + delta < 1 || (delta > 0 && (orders.total === null || orders.page * orderPageSize >= orders.total))) return; orders.page += delta; void loadOrders(); }
async function createOrder() { const context = checkout.value; if (!current() || busy.value || !context?.payload || context.stale) return; const req = scope('checkout'); busy.value = 'create'; context.error = ''; saveRecovery(context.payload); try { const result = await api.post('/order/create', context.payload, { signal: req.signal }); if (!req.current() || checkout.value !== context) return; if (!ownOrderId(result?.orderId)) throw new Error('订单结果不完整'); context.order = result; saveRecovery(null); busy.value = ''; void loadOrders(); if (result.status === 0) await preparePayment(); else if (result.status === 1) void sharedBalance.refresh(); } catch (e) { if (!req.current() || checkout.value !== context) return; if (e.status === 409 || e.status === 400 || e.status === 404) { context.error = e.message || '套餐或订单已更新，请重新选择。'; context.stale = true; saveRecovery(null); } else { context.error = '下单结果尚未确认。可用同一次请求继续确认，不会重新创建第二笔订单。'; context.recovering = true; } } finally { if (req.current() && checkout.value === context) busy.value = ''; } }
async function refreshChangedOffer() { closeCheckout(); await loadOffers(); }
async function preparePayment() { const context = checkout.value; if (!current() || busy.value || context?.order?.status !== 0 || context.paymentUncertain) return; const req = scope('checkout'); busy.value = 'prepare'; context.error = ''; context.prep = null; try { const prep = await api.post(orderPath('prepare', context.order.orderId), {}, { signal: req.signal }); if (!req.current() || checkout.value !== context) return; if (!prep?.mock && !paymentHref(prep?.payUrl)) throw new Error('付款地址无效，请联系站点管理员。'); context.prep = prep; } catch (e) { if (req.current() && checkout.value === context) { context.error = e.message || '付款方式尚未准备好，订单仍保留。'; if (e.status === 409) context.paymentUncertain = true; } } finally { if (req.current() && checkout.value === context) busy.value = ''; } }
async function openOrder(id, event) { if (!ownOrderId(id) || busy.value || !current()) return; await showCheckout({ order: null, payload: null, error: '', statusError: '' }, event); const context = checkout.value; if (!current() || !context) return; const req = scope('checkout'); busy.value = 'detail'; try { const data = await api.get(orderPath('detail', id), { signal: req.signal }); if (req.current() && checkout.value === context) context.order = data; } catch (e) { if (req.current() && checkout.value === context) { context.error = e.message || '订单暂未读取成功'; context.stale = true; } } finally { if (req.current() && checkout.value === context) busy.value = ''; } }
async function refreshStatus() { const context = checkout.value; if (!current() || !dialog.value?.open || !context?.order || busy.value) return; const req = scope('status'); try { const status = await api.get(orderPath('status', context.order.orderId), { signal: req.signal }); if (!req.current() || checkout.value !== context) return; const prior = context.order.status; context.order = { ...context.order, ...status }; context.statusError = ''; context.paymentUncertain = false; if (status.status !== 0) context.prep = null; if (prior !== status.status) { void loadOrders(); if (status.status === 1) void sharedBalance.refresh(); } } catch { if (req.current() && checkout.value === context) context.statusError = '支付状态暂未更新，请稍后刷新确认。'; } }
async function confirmMockPayment() { await mutateOrder('mock'); }
async function closeOrder() { await mutateOrder('close'); }
async function mutateOrder(action) { const context = checkout.value; if (!current() || busy.value || context?.order?.status !== 0 || context.paymentUncertain || action === 'mock' && !context.prep?.mock) return; controllers.get('status')?.abort(); const req = scope('checkout'); busy.value = action; context.error = ''; context.prep = null; try { const result = await api.post(orderPath(action, context.order.orderId), {}, { signal: req.signal }); if (!req.current() || checkout.value !== context) return; context.order = { ...context.order, ...result }; context.prep = null; void loadOrders(); if (context.order.status === 1) void sharedBalance.refresh(); } catch (e) { if (req.current() && checkout.value === context) { context.paymentUncertain = true; context.error = e.status === 409 ? '订单状态已变化，请刷新确认。' : '操作结果尚未确认，请先刷新订单状态。'; } } finally { if (req.current() && checkout.value === context) busy.value = ''; } }
function closeCheckout(restore = true) { controllers.get('checkout')?.abort(); controllers.get('status')?.abort(); busy.value = busy.value === 'redeem' ? 'redeem' : ''; if (dialog.value?.open) dialog.value.close(); checkout.value = null; const target = opener; opener = null; if (restore && target?.isConnected) target.focus({ preventScroll: true }); }
function onDialogClosed() { if (!dialog.value?.open && checkout.value) closeCheckout(); }
function onBackdrop(event) { if (event.target !== dialog.value) return; const r = dialog.value.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) closeCheckout(); }
function onCodeEnter(event) { event.preventDefault(); if (!event.isComposing) void redeem(); }
async function redeem() { const normalized = cardCode(code.value); if (!current() || busy.value || redeemUncertain.value) return; grant.value = null; if (!normalized) { redeemMessage.value = '请输入 12 位字母数字卡密，可包含空格或横线。'; return; } const req = scope('redeem'); busy.value = 'redeem'; redeemMessage.value = ''; try { const data = await api.post('/crami/exchange', { code: normalized }, { signal: req.signal }); if (!req.current()) return; grant.value = data.granted || {}; code.value = ''; void sharedBalance.refresh(); } catch (e) { if (!req.current()) return; redeemUncertain.value = !e.status || e.status >= 500; redeemMessage.value = redeemUncertain.value ? '兑换结果尚未确认，请先查看兑换记录，避免重复提交。' : e.message || '兑换未完成，请核对卡密。'; } finally { if (req.current()) busy.value = ''; } }
function scrollTo(id) { document.getElementById(id)?.scrollIntoView({ behavior: document.documentElement.dataset.qgMotion === 'quiet' || window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' }); }
watch(orderFilter, () => { orders.page = 1; void loadOrders(); });
watch(code, (value, prior) => { if (cardCode(value) !== cardCode(prior)) { redeemUncertain.value = false; redeemMessage.value = ''; } });
watch(() => route.query.order, id => { if (ownOrderId(id)) void openOrder(id); });
function clear() { for (const controller of controllers.values()) controller.abort(); controllers.clear(); closeCheckout(false); offers.value = []; orders.items = []; orders.total = null; orders.page = 1; orders.loading = false; orders.error = ''; amount.value = ''; amountError.value = ''; code.value = ''; grant.value = null; redeemMessage.value = ''; redeemUncertain.value = false; recovery.value = null; busy.value = ''; offerFilter.value = ''; orderFilter.value = ''; disabled.value = false; catalogError.value = ''; }
watch(() => auth.user?.id, id => { if (id === owner) return; try { sessionStorage.removeItem(recoveryKey()); } catch {} clear(); owner = id; if (id) void initialize(); });
async function initialize() { readRecovery(); await loadOffers(); if (current() && !disabled.value) { void loadOrders(); if (ownOrderId(route.query.order)) void openOrder(route.query.order); } }
onMounted(() => { void initialize(); poller = setInterval(() => { if (!document.hidden && dialog.value?.open && checkout.value?.order?.status === 0) void refreshStatus(); }, 4000); });
onBeforeUnmount(() => { alive = false; clearInterval(poller); clear(); });
</script>
